# Generated by build.py from recipe.yml for recipe http-prove-a-client-uses-its-proxy. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/prices.json'), "{`"widget`": 3}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'via-proxy.awk'), "{ sub(/\r`$/, `"`") }`n# A request head in origin form (GET /path) is one the origin received.`n/^[0-9a-f]+: [A-Z]+ \// { open = 1; via = 0; next }`nopen && /^[0-9a-f]+: Via: 1\.1 surl`$/ { via = 1 }`n# The blank line that ends the head.`nopen && /^[0-9a-f]+: ?`$/ { if (via) proxied++; else direct++; open = 0 }`nEND {`n  printf `"%d via the proxy, %d direct\n`", proxied, direct`n  exit (direct > 0)`n}`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--trace-ascii', 'traffic.txt', 'http://127.0.0.1:8080/', '--proxy', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS -x http://127.0.0.1:8081/ -o hello.txt http://127.0.0.1:8080/hello.txt -o prices.json http://127.0.0.1:8080/prices.json
try { awk -f via-proxy.awk traffic.txt } finally { Stop-Process $server0 }
